import{_ as l,l as o,o as t,c as i,v as E,p as d,x as s,d as r,i as p,S as h,b as e}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"指数 vs 单名","description":"","frontmatter":{"title":"指数 vs 单名","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cdx-vs-single.md","filePath":"quant/cdx-vs-single.md","lastUpdated":1789023840000}'),c={name:"quant/cdx-vs-single.md"};function u(B,a,C,D,S,k){const n=o("Mermaid");return t(),i("div",null,[a[1]||(a[1]=E('<h1 id="指数-vs-单名" tabindex="-1">指数 vs 单名 <a class="header-anchor" href="#指数-vs-单名" aria-label="Permalink to &quot;指数 vs 单名&quot;">​</a></h1><div class="epigraph"><p>指数 CDS 报的是一篮子同等名义的组合保护，不是单名升水的算术平均；流动性、构成滚动与相关性会使指数相对内在价值出现持续的 skew。</p><footer>—— 对照 CDX / iTraxx 市场惯例与指数–单名基差的交易实践</footer></div><p><a href="/quant/cds-bond-basis">上一课</a>把 CDS–债券基差写成两份不同合约的价差：非资金保护对融资后的现金信用；并点名指数对冲还会叠上 skew 与滚动。缺口正是那一层：指数报价便捷，却回答不了篮子里每一个名字值多少。本课写 CDX / iTraxx 对单名、内在升水与 skew。不重讲 CTD 与负基差的融资约束。后课高斯 Copula 分层默认已经读完：未分层指数升水不是违约相关的充分统计。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>指数报价便捷，却回答不了「篮子里每一个名字值多少」。内在价值（intrinsic / theoretical）通常用各单名的同一到期升水或预付，按指数规则合成：等权、考虑已违约名字、用标准票息与回收假设把预付加总。指数市场价可以比内在更贵或更便宜。正 skew（指数比内在贵）表示组合保护的需求高于单名加总，常见于对冲压力、单名流动性枯竭、或市场在买相关性。负 skew 则可能来自经销商用指数对冲单名库存的反向。</p><p>第二个问题是对冲误差。用 CDX IG 对冲一个不等权、行业偏斜的信用组合，剩下的是构成差异、评级迁移进出指数、以及特异违约。指数只对「系列里等权的那些名字」提供保护。滚动时 on-the-run 与 off-the-run 会分裂成两条曲线，旧系列逐渐变成更像一篮子静态单名。</p><h3 id="指数不是违约相关的充分统计" tabindex="-1">指数不是违约相关的充分统计 <a class="header-anchor" href="#指数不是违约相关的充分统计" aria-label="Permalink to &quot;指数不是违约相关的充分统计&quot;">​</a></h3><p>未分层的指数升水主要对违约强度的平均水平敏感，对名字之间的相关不那么敏感：一阶上它接近单名保护的组合。相关进入价格的主战场是分层（tranche）：股权层吃前几笔违约，超优先层吃相关升上去之后的共同违约。用指数升水去推断「市场隐含相关」是信息不足的；那是 tranche 与基相关（base correlation）的工作。把 CDX 当成「系统性信用因子」可以，把它当成 CDO 相关的观测不行。</p><p><span class="marginnote">指数系列有固定的构成日。新系列会丢掉已恶化或已升到另一评级篮子的名字，加入新名字。用跨系列的升水时间序列当同一指数，会把构成效应当成利差变动。研究必须按系列编号对齐，或使用发行人匹配的单名组合。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>内在价值。</strong> 对每个存活名字计算标准票息下的 CDS 预付（或平价升水再转预付），等权加总，按指数惯例处理已触发名字的固定回收结算。得到的组合预付再转成指数升水，与市场报价比较，差为 skew。单名缺失时要用代理曲线，代理误差会直接进入「假 skew」。</p><p><strong>对冲。</strong> 宏观对冲：用 on-the-run 指数对冲组合的 CS01，再按行业或评级用子指数或单名补残差。复制：买/卖指数、对冲掉每一个单名，做的是 skew 交易。滚动：在滚动窗口把旧系列换成新系列，滚动价差本身是流动性与构成的价格。分层对冲：用指数对冲分层的 delta，相关风险留在 vega / 基相关上。</p><p><strong>压缩与清算。</strong> 指数比单名更容易进入中央清算与压缩周期，保证金更标准化。这会把一部分对手方与资金优势写进指数价格，使 skew 含清算便利，而不只是违约相关。</p><h3 id="从等权篮子到交易簿的-cs01" tabindex="-1">从等权篮子到交易簿的 CS01 <a class="header-anchor" href="#从等权篮子到交易簿的-cs01" aria-label="Permalink to &quot;从等权篮子到交易簿的 CS01&quot;">​</a></h3><p>组合的信用 CS01 按发行人权衡；指数的 CS01 按等权。对冲比是两条 CS01 向量的投影，不是名义相等。高收益组合用 IG 指数对冲，会留下质量和凸性残差：利差走阔时 HY 的 CS01 上升更快。应定期重算对冲比，并限制单名相对指数的残余集中度。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>指数流动性来自标准化：同一个系列、同一套票息、大量对手方在同一工具上做市。单名是分散的 OTC 曲线，许多名字几天没有可成交报价。于是系统性冲击先打在指数上，再缓慢传到单名，skew 在压力里可以迅速拉大。这与股票里指数期货对一篮子现货的基差同构，只是信用的「现货」更不流动。</p><p>构成滚动制造一个机械的质量偏置：定期踢出最差的名字，指数会比「曾经在篮子里的那些发行人」的长期组合更干净。长期用 on-the-run 升水当信用周期指标，会低估真实信贷恶化——恶化的名字已经被滚出样本。这与股票指数的幸存者问题同类，见信用研究里对 <a href="/quant/rating-migration">评级迁移</a> 与样本选择的讨论。</p><p><span class="marginnote">违约后指数名义下降，剩余保护对着还活着的名字。把指数当成固定名义的「平均 CDS」会在一连串违约后算错 CS01。风险系统必须按当前因子（factor）与剩余名义重定价。</span></p><h3 id="skew-作为相关与流动性的混合物" tabindex="-1">Skew 作为相关与流动性的混合物 <a class="header-anchor" href="#skew-作为相关与流动性的混合物" aria-label="Permalink to &quot;Skew 作为相关与流动性的混合物&quot;">​</a></h3><p>Skew 在相关冲击里会动：交易员买指数保护、卖单名保护（或反向）来表达「违约会更一起发生」。但同样的价差也会被单名买卖价差、指数轧差便利、系列切换库存推动。没有分层报价时，不要把 skew 的全部变动写成隐含相关。有分层时，应把指数、单名与 tranche 放在同一日历上对账，否则相关表面会吞掉同步误差。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要用指数升水去标定每一个单名的 \\(\\lambda\\)，除非声明这是映射。不要在篮子与指数构成差了二十个名字时，还把残差 PnL 叫做 alpha。不要忽略滚动：回测若总是用最新系列，实际交易却常被迫留在旧系列上，成本和升水都不同。主权与公司指数的规则、重组条款、可交割定义不同，不能共用一套转换。</p><p>单名保护在困境里可能完全没有出价，指数仍可交易：此时「内在价值」用的是过时或宽价差的单名，skew 会假得很大。工程上应对缺失单名做标记（staleness），并在 skew 交易上加流动性折扣。指数期权、收盘拍卖与 Markit 定价服务会提供额外的结算锚，但它们不是可执行的单名曲线。</p><p><span class="marginnote">用指数做空信用、用少数单名做多「精选」信用，是常见的相对价值形态。它的主要风险往往是 skew 与滚动，而不是你选中的那几个基本面故事。归因时应把指数腿单独拆出来。</span></p>',25)),(t(),d(h,null,{default:s(()=>[p(n,{id:"mermaid-73",class:"mermaid",graph:"flowchart%20TD%0A%20%20SN%5B%22%E5%8D%95%E5%90%8D%20CDS%20%E6%9B%B2%E7%BA%BF%22%5D%20--%3E%20INT%5B%22%E5%86%85%E5%9C%A8%E7%AF%AE%E5%AD%90%E9%A2%84%E4%BB%98%20%2F%20%E5%8D%87%E6%B0%B4%22%5D%0A%20%20IDX%5B%22%E6%8C%87%E6%95%B0%E5%B8%82%E5%9C%BA%E6%8A%A5%E4%BB%B7%22%5D%20--%3E%20SK%5B%22Skew%20%3D%20%E6%8C%87%E6%95%B0%20-%20%E5%86%85%E5%9C%A8%22%5D%0A%20%20INT%20--%3E%20SK%0A%20%20IDX%20--%3E%20HEDGE%5B%22%E5%AE%8F%E8%A7%82%20CS01%20%E5%AF%B9%E5%86%B2%22%5D%0A%20%20SN%20--%3E%20RES%5B%22%E7%89%B9%E5%BC%82%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20HEDGE%20--%3E%20RES%0A%20%20IDX%20--%3E%20TR%5B%22%E5%88%86%E5%B1%82%20%2F%20%E5%9F%BA%E7%9B%B8%E5%85%B3%22%5D%0A%20%20SK%20--%3E%20LIQ%5B%22%E6%B5%81%E5%8A%A8%E6%80%A7%20%2B%20%E7%9B%B8%E5%85%B3%20%2B%20%E6%9E%84%E6%88%90%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"小结",tabindex:"-1"},[r("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=e("ul",null,[e("li",null,"指数 CDS 是等权篮子的标准化保护，流动性远好于单名，但构成随系列滚动而变。"),e("li",null,"内在价值由单名按指数规则合成；与指数报价之差是 skew，混有流动性、清算便利与相关需求。"),e("li",null,"未分层指数对平均强度敏感，对相关不充分；相关主要由 tranche 与基相关交易。"),e("li",null,"用指数对冲组合必须按 CS01 投影并管理构成、质量与滚动残差。"),e("li",null,"出处：CDX / iTraxx 指数规则与 ISDA 标准 CDS 模型；定价框架承接 Duffie 的单名 CDS 估值；分层定价的相关部分见 Li 的高斯 Copula 及其后的基相关惯例。")],-1))])}const f=l(c,[["render",u]]);export{m as __pageData,f as default};
